package storage

import (
	"context"
	"errors"
	"fmt"
)

var ErrAdminAlreadyExists = errors.New("an admin account already exists")

// Stable application-specific key for serializing first-admin bootstrap.
const adminBootstrapLockKey int64 = 0x455753545250

// BootstrapAdmin creates the first admin in the default tenant exactly once.
// The passwordHash must already have been generated by auth.HashPassword.
func (s *Store) BootstrapAdmin(
	ctx context.Context,
	email string,
	passwordHash string,
) (*User, error) {
	if s == nil || s.DB == nil {
		return nil, errors.New("bootstrap admin: storage is unavailable")
	}

	tx, err := s.DB.BeginTx(ctx, nil)
	if err != nil {
		return nil, fmt.Errorf("bootstrap admin: begin transaction: %w", err)
	}
	defer func() {
		_ = tx.Rollback()
	}()

	_, err = tx.ExecContext(
		ctx,
		`SELECT pg_advisory_xact_lock($1)`,
		adminBootstrapLockKey,
	)
	if err != nil {
		return nil, fmt.Errorf("bootstrap admin: acquire lock: %w", err)
	}

	var adminExists bool
	err = tx.QueryRowContext(ctx, `
SELECT EXISTS (
    SELECT 1
    FROM users
    WHERE role = 'admin'
)
`).Scan(&adminExists)
	if err != nil {
		return nil, fmt.Errorf("bootstrap admin: check existing admin: %w", err)
	}

	if adminExists {
		return nil, ErrAdminAlreadyExists
	}

	var tenantID string
	err = tx.QueryRowContext(ctx, `
SELECT tenant_id::text
FROM tenants
WHERE slug = 'default'
  AND is_active = TRUE
`).Scan(&tenantID)
	if err != nil {
		return nil, fmt.Errorf("bootstrap admin: resolve default tenant: %w", err)
	}

	user, err := createUser(ctx, tx, tenantID, email, passwordHash, "admin")
	if err != nil {
		return nil, fmt.Errorf("bootstrap admin: %w", err)
	}

	if err := tx.Commit(); err != nil {
		return nil, fmt.Errorf("bootstrap admin: commit transaction: %w", err)
	}

	return user, nil
}
